  && value.trim().length <= 120 && !/[<>\u0000-\u001f]/.test(value);
const isRecord = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const catalogFingerprint = v => typeof v === 'string' && /^[a-f\d]{32}$/.test(v);
