          !Array.isArray(answer.items) || !Number.isSafeInteger(answer.catalogVersion) ||
          answer.catalogVersion < 1 || answer.scope !== scope ||
          answer.classificationAuthority !== 'NONE' || answer.notificationAuthority !== 'NONE')
