      if (answer.nextAfter === null) { completed = true; break; }
      if (typeof answer.nextAfter !== 'string' || !answer.nextAfter.length ||
          seenCursors.has(answer.nextAfter)) catalogError('INVALID_CURSOR');
      seenCursors.add(answer.nextAfter);
