    ...(fingerprint !== null ? { catalogFingerprint: fingerprint } : {}),
    categories: Array.from(byId.values()).map(node => Object.freeze({
      ...node, modes: Object.freeze(Array.from(scopesById.get(node.id)).sort()),
    })),
