  }
  if (['CREATE_CHILD','CREATE_NEW_BRANCH','PROPOSE_RESTRUCTURE'].includes(plan.action)) {
    if (navigated && ['CREATE_CHILD','CREATE_NEW_BRANCH'].includes(plan.action)) {
      if (identityCheck.categoryIds.length)
        return { accepted: false, status: 'EXISTING_IDENTITY_REQUIRES_REVIEW' };
      if (!snapshot.navigation.searchedServices?.includes(identity))
        return { accepted: false, status: 'CATALOG_RESEARCH_REQUIRED' };
    }
    if (plan.action === 'CREATE_CHILD') {
      const parent = categories.get(plan.parentId);
      if (!parent) return { accepted: false, status: 'UNKNOWN_PARENT_ID' };
      // Parent links organize meanings. Only the actual service has execution
      // modes; a new child does not inherit or extend its parent's capabilities.
    }
    if (!Array.isArray(plan.proposedPath) || !plan.proposedPath.length ||
        new TextEncoder().encode(JSON.stringify(plan.proposedPath)).byteLength > 12000 || !plan.proposedPath.every(safeLabel))
      return { accepted: false, status: 'INVALID_PATH' };
    if (plan.action !== 'PROPOSE_RESTRUCTURE' &&
        normalizedClassificationIdentity(plan.proposedPath.at(-1)) !==
        normalizedClassificationIdentity(input.service))
      return { accepted: false, status: 'SERVICE_LEAF_MISMATCH' };
    if (plan.action === 'CREATE_NEW_BRANCH' && plan.parentId != null)
      return { accepted: false, status: 'NEW_BRANCH_MUST_HAVE_NO_PARENT' };
    return { accepted: false, status: 'ADMISSION_REVIEW_REQUIRED',
      catalogVersion: snapshot.catalogVersion, capabilityAuthority: 'NONE',
      notificationAuthority: 'NONE' };
  }
  return { accepted: false, status: plan.action,
    catalogVersion: snapshot.catalogVersion, capabilityAuthority: 'NONE',
    notificationAuthority: 'NONE' };
}

/** Complete current catalog, never a relevance shortlist. Parent links preserve
 * every branch without repeating the entire ancestry on each row. Resource
 * exhaustion is an explicit read failure, never evidence a service is absent.
 * Fresh catalog loading and the signed review both fence concurrent changes.
 */
export function catalogPromptContext(snapshot) {
  if (!isRecord(snapshot) || !Array.isArray(snapshot.categories) ||
      !Number.isSafeInteger(snapshot.catalogVersion) || snapshot.catalogVersion < 1)
    catalogError('PROMPT_INVALID');
  const all = snapshot.categories;
  const byId = new Map(all.map(node => [node.id, node]));
  if (byId.size !== all.length) catalogError('DUPLICATE_ID');
  const finished = new Set();
  for (const node of all) {
    let current = node;
    const chain = new Set();
    while (current && !finished.has(current.id)) {
      if (chain.has(current.id)) catalogError('CYCLIC_ANCESTRY');
      chain.add(current.id);
      if (current.parentId == null) break;
      current = byId.get(current.parentId);
      if (!current) catalogError('INCOMPLETE_ANCESTRY');
    }
    for (const id of chain) finished.add(id);
  }
  return JSON.stringify({
    catalogVersion: snapshot.catalogVersion,
    catalogFingerprint: snapshot.catalogFingerprint ?? null,
    classificationAuthority: 'NONE',
    shortlisted: false,
    totalCategories: all.length,
    complete: true,
    instructions: 'This is the COMPLETE current eligible catalog across ON_SITE and REMOTE, not a shortlist. All nodes and registered aliases are included. Follow parentId links upward to roots and downward through children; compare all branches before proposing novelty. Select the narrowest existing service with exactly the same work, object and scope. Related, broader or narrower work is NOT equivalent. Never invent IDs. A missing exact phrase is not proof of a missing service: understand the meaning and clarify ambiguous work. For a clearly equivalent natural description, use the precise canonical service name in the reviewed skills/task category while preserving the person\'s actual scope in bio/description. Do not add services they never offered. New branches must be meaningful and non-duplicative; propose the necessary path, never create or activate it during chat. Mode and owner Save remain separate confirmations.',
    categories: all.map(node => ({
      id: node.id, parentId: node.parentId, label: node.label, modes: node.modes,
      ...(catalogFingerprint(snapshot.catalogFingerprint) && validAliases(node.aliases)
        ? { aliases: node.aliases } : {}),
    })),
  });
}

// Shared wire validation only. Country syntax is not a shipping promise and a
// city label is not an exact address or an authoritative geographic identifier.
const record = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const exact = (value, keys) => record(value) && Object.keys(value).length === keys.length && keys.every(key => Object.hasOwn(value, key));
const country = value => typeof value === 'string' && /^[A-Z]{2}$/.test(value);
const utf8Length = text => { let bytes = 0; for (const char of text) { const point = char.codePointAt(0); bytes += point <= 0x7f ? 1 : point <= 0x7ff ? 2 : point <= 0xffff ? 3 : 4; } return bytes; };

/** Return a detached, unchanged value or null. Never sort/normalize facts behind
 * a signed review's back. Missing is UNKNOWN, never unrestricted physical delivery.
 */
export function decodeServiceHandoff(value) {
  if (!record(value) || !Object.hasOwn(value, 'required')) return null;
  try { if (utf8Length(JSON.stringify(value)) > 2048) return null; }
  catch { return null; }
  if (value.required === false) return exact(value, ['required']) ? { required: false } : null;
  if (value.required !== true || Object.keys(value).some(key => !['required', 'shippingCountries', 'localExchange'].includes(key))) return null;
  const shipping = Object.hasOwn(value, 'shippingCountries'), local = Object.hasOwn(value, 'localExchange');
  if (!shipping && !local) return null;
  if (shipping && (!Array.isArray(value.shippingCountries) || value.shippingCountries.length < 1 || value.shippingCountries.length > 32
      || !Array.from(value.shippingCountries).every(country) || new Set(value.shippingCountries).size !== value.shippingCountries.length)) return null;
  if (local && (!exact(value.localExchange, ['countryCode', 'city']) || !country(value.localExchange.countryCode)
      || typeof value.localExchange.city !== 'string' || Array.from(value.localExchange.city).length < 3 || Array.from(value.localExchange.city).length > 120
      || value.localExchange.city !== value.localExchange.city.trim() || /[<>\u0000-\u001f\u007f-\u009f\d]/.test(value.localExchange.city))) return null;
  return { required: true, ...(shipping ? { shippingCountries: value.shippingCountries.slice() } : {}),
    ...(local ? { localExchange: { countryCode: value.localExchange.countryCode, city: value.localExchange.city } } : {}) };
}

/** Shared owner-visible summary; countries retain the reviewed input order. */
export function formatServiceHandoff(value) {
  const handoff = decodeServiceHandoff(value);
  if (!handoff) return null;
  if (!handoff.required) return 'Bez fizičke predaje';
  return [handoff.shippingCountries ? 'Slanje: ' + handoff.shippingCountries.join(', ') : null,
    handoff.localExchange ? `Lično preuzimanje: ${handoff.localExchange.city} (${handoff.localExchange.countryCode})` : null]
    .filter(Boolean).join(' ili ');
}

// Count-only latency evidence. No prompts, IDs, coordinates, provider bodies or errors.
// A telemetry failure must never change the operation's result or retry it.
const phases = new Set(['PROVIDER', 'CATALOG_TOOLS', 'ADMISSION', 'ACCOUNTING',
  'NEED_CATALOG_START', 'NEED_CATALOG_VERIFY', 'NEED_BG_ARCHITECT', 'NEED_COMPLETE', 'NEED_HINT_CAPTURE',
  'WORKER_CATALOG_START', 'WORKER_CATALOG_VERIFY', 'WORKER_BG_ARCHITECT', 'WORKER_COMPLETE', 'WORKER_HINT_CAPTURE']);
/** @template T
 * @param {string} phase
 * @param {() => Promise<T>} operation
 * @returns {Promise<T>}
 */
export async function measureAiPhase(phase, operation) {
  const started = Date.now();
  let succeeded = false;
  try {
    const result = await operation();
    succeeded = true;
    return result;
  } finally {
    try { console.info('AI_PHASE_MS', phases.has(phase) ? phase : 'UNKNOWN',
      Math.max(0, Date.now() - started), succeeded ? 'SUCCEEDED' : 'FAILED'); }
    catch { /* Logging never changes delivery or accounting. */ }
  }
}

/**
 * One server-only owner of optional taxonomy AI rollout flags (A30-D04/D05).
 * All optional capabilities are default OFF, including on DEV. Explicit false
 * and missing config both close them; a paid background classifier additionally
 * needs a verified DEV project scope and the existing paid-test admission flag.
 *
 * This is not provider budget authority. Every paid operation still passes the
 * current reservation, durable turn and usage fences. No URL, ref or secret is
 * embedded in the source and no request/client input can enable a feature.
 */
const OPTIONAL = new Set(['USKOCI_TAXONOMY_DIRECT_REPLY','USKOCI_TAXONOMY_UNIFIED_SHADOW','USKOCI_TAXONOMY_SHADOW_CAPTURE']);
export function taxonomyOptionalEnabled(get, name) {
  return typeof get === 'function' && OPTIONAL.has(name) && get(name) === 'true';
}
export function taxonomyDualGeminiEnabled(get) {
  if (typeof get !== 'function' || get('USKOCI_TAXONOMY_DUAL_GEMINI') !== 'true'
    || get('USKOCI_GEMINI_PAID_TEST_ENABLED') !== 'true'
    || !get('SUPABASE_ANON_KEY') || get('USKOCI_TAXONOMY_ROLLOUT_SCOPE') !== 'DEV') return false;
  const allowed = get('USKOCI_TAXONOMY_ALLOWED_PROJECT_REF');
  if (typeof allowed !== 'string' || !/^[a-z0-9]{20}$/.test(allowed)) return false;
  try {
    const target = new URL(get('SUPABASE_URL') ?? '');
    // Permit the platform's standard trailing slash, but no alternate paths,
    // embedded credentials, query, port, or lookalike host.
    return target.protocol === 'https:' && target.username === '' && target.password === ''
      && !target.port && target.pathname === '/' && !target.search && !target.hash
      && target.hostname === allowed + '.supabase.co';
  } catch { return false; }
}

