// Shared V5 controlled-provider test budget. No retries or refunds after uncertain I/O.
export const AI_TEST_LIMITS = Object.freeze({
  // Per model call, not catalog capacity. Navigation avoids whole-tree prompts.
  // Text budget doubled after adding paged tool results; output remains bounded.
  llmRequestBytes: 262144,
  llmMaxOutputTokens: 8192,
  llmReservationMicrousd: 250000,
  speechPcmBytes: 3840000,
  speechMaxOutputTokens: 8192,
  speechReservationMicrousd: 200000,
  speechCaptureMs: 120000,
  speechFinalizationMs: 15000,
});

export type AiTestBudgetResult = {
  admitted: boolean;
  reservationId: string | null;
  replay: boolean;
  code: string;
};

export async function reserveAiTestBudget(input: {
  supabaseUrl: string; serviceRoleKey: string; accountId: string; operationId: string;
  kind: 'LLM' | 'STT'; signal?: AbortSignal;
}): Promise<AiTestBudgetResult> {
  const abort = new AbortController();
  const stop = () => abort.abort();
  const timeout = setTimeout(stop, 5000);
  input.signal?.addEventListener('abort', stop, { once: true });
  if (input.signal?.aborted) stop();
  // A response body or fetch implementation may ignore AbortSignal. The five-
  // second budget and caller cancellation must still settle this reservation.
  // Do not interpret an interrupted reservation as proof of no provider charge
  // or automatically create another paid operation.
  const cancelled=new Promise<never>((_,reject)=>{
    const onAbort=()=>reject(new Error('AI_TEST_BUDGET_UNAVAILABLE'));
    if(abort.signal.aborted)onAbort();
    else abort.signal.addEventListener('abort',onAbort,{once:true});
  });
  void cancelled.catch(()=>undefined);
  const assertActive = () => {
    if (abort.signal.aborted) throw new Error('AI_TEST_BUDGET_UNAVAILABLE');
  };
  try {
    assertActive();
    const response = await Promise.race([fetch(input.supabaseUrl + '/rest/v1/rpc/rpc_ai_test_budget_reserve_service', {
      method: 'POST', redirect: 'error', signal: abort.signal,
      headers: { 'Content-Type': 'application/json', apikey: input.serviceRoleKey, Authorization: 'Bearer ' + input.serviceRoleKey },
      body: JSON.stringify({ p_account_id: input.accountId, p_operation_id: input.operationId, p_kind: input.kind,
        p_max_cost_microusd: input.kind === 'LLM' ? AI_TEST_LIMITS.llmReservationMicrousd : AI_TEST_LIMITS.speechReservationMicrousd }),
    }),cancelled]);
    if (abort.signal.aborted || !response.ok || !response.body) {
      // The deadline may win just before headers resolve. Cleanup MUST NOT
      // replace the original budget refusal with a TypeError, even for a
      // nonstandard transport that only exposes getReader().cancel().
      // Do not await cleanup: its promise may ignore cancellation too.
      try {
        const body=response.body;
        if (body && typeof body.cancel==='function')
          void Promise.resolve(body.cancel()).catch(()=>undefined);
        else if (body && typeof body.getReader==='function') {
          const reader=body.getReader();
          if (typeof reader.cancel==='function')
            void Promise.resolve(reader.cancel()).catch(()=>undefined);
        }
      } catch { /* best effort, never changes the conservative refusal */ }
      throw new Error('AI_TEST_BUDGET_UNAVAILABLE');
    }
    const reader = response.body.getReader();
    let content = '', length = 0;
    try {
      const decoder = new TextDecoder();
      while (true) {
        const part = await Promise.race([reader.read(),cancelled]);
        assertActive();
        if (part.done) break;
        length += part.value.byteLength;
        if (length > 4096) throw new Error('AI_TEST_BUDGET_UNAVAILABLE');
        content += decoder.decode(part.value, { stream: true });
      }
      content += decoder.decode();
    } finally { void reader.cancel().catch(() => undefined); }
    const result = JSON.parse(content);
    const codes = ['AI_TEST_RESERVED','AI_TEST_OPERATION_REPLAY','AI_TEST_BUDGET_NOT_READY','AI_TEST_ACCOUNT_NOT_ADMITTED','AI_TEST_BUDGET_EXHAUSTED'];
    if (!result || Object.keys(result).length !== 4 || typeof result.admitted !== 'boolean' || typeof result.replay !== 'boolean'
      || !codes.includes(result.code) || !(result.reservationId === null || /^[0-9a-f-]{36}$/i.test(result.reservationId))
      || (result.admitted && (result.replay || result.code !== 'AI_TEST_RESERVED' || !result.reservationId))) {
      throw new Error('AI_TEST_BUDGET_UNAVAILABLE');
    }
    assertActive();
    return result;
  } finally { clearTimeout(timeout); input.signal?.removeEventListener('abort', stop); stop(); }
}

// The speech session uses waitUntil for these two receipts. AbortSignal alone
// cannot settle a transport/body that ignores cancellation; bound the wait as
// well, and keep an uncertain write unconfirmed without retrying it.
async function postAudioBudgetReceipt(input: {
  supabaseUrl: string; serviceRoleKey: string;
}, rpc: 'rpc_ai_test_release_unused_reservation_service' | 'rpc_ai_test_settle_audio_service',
args: Record<string, unknown>): Promise<Record<string, unknown>> {
  const abort = new AbortController();
  const stopped = new Promise<never>((_, reject) => {
    abort.signal.addEventListener('abort', () => reject(new Error('AI_TEST_ACCOUNTING_UNCONFIRMED')), { once: true });
  });
  void stopped.catch(() => undefined);
  const timeout = setTimeout(() => abort.abort(), 5000);
  const check = () => { if (abort.signal.aborted) throw new Error('AI_TEST_ACCOUNTING_UNCONFIRMED'); };
  try {
    const request = fetch(input.supabaseUrl + '/rest/v1/rpc/' + rpc, {
      method: 'POST', redirect: 'error', signal: abort.signal,
      headers: { 'Content-Type': 'application/json', apikey: input.serviceRoleKey, Authorization: 'Bearer ' + input.serviceRoleKey },
      body: JSON.stringify(args),
    }).then(response => {
      if (abort.signal.aborted || !response.ok || response.redirected || !response.body) {
        try { void response.body?.cancel().catch(() => undefined); } catch { /* best effort cleanup */ }
        throw new Error('AI_TEST_ACCOUNTING_UNCONFIRMED');
      }
      return response;
    });
    const response = await Promise.race([request, stopped]);
    check();
    const reader = response.body!.getReader();
    let raw = '', length = 0;
    try {
      const decoder = new TextDecoder('utf-8', { fatal: true });
      while (true) {
        const part = await Promise.race([reader.read(), stopped]);
        check();
        if (part.done) break;
        length += part.value.byteLength;
        if (length > 4096) throw new Error('AI_TEST_ACCOUNTING_UNCONFIRMED');
        raw += decoder.decode(part.value, { stream: true });
      }
      raw += decoder.decode();
    } finally { try { void reader.cancel().catch(() => undefined); } catch { /* best effort cleanup */ } }
    check();
    const receipt: unknown = JSON.parse(raw);
    if (!receipt || typeof receipt !== 'object' || Array.isArray(receipt)) throw new Error('AI_TEST_ACCOUNTING_UNCONFIRMED');
    return receipt as Record<string, unknown>;
  } finally { clearTimeout(timeout); abort.abort(); }
}

/** Only call with proof that no audio was dispatched and no provider output observed.
 * Missing output after dispatch is UNKNOWN, never proof of zero cost. The RPC also
 * refuses release when usage exists, but absence of recorded usage is not that proof. */
export async function releaseUnusedAiTestReservation(input: {
  supabaseUrl: string; serviceRoleKey: string; operationId: string;
}): Promise<boolean> {
  try {
    const body = await postAudioBudgetReceipt(input, 'rpc_ai_test_release_unused_reservation_service', { p_operation_id: input.operationId });
    return body.operationId === input.operationId && body.released === true && body.code === 'AI_RELEASE_DONE';
  } catch { return false; }
}

/** A fully completed session uses the existing duration/output estimate, not a provider
 * invoice. Partial/unknown completion keeps its hold. The RPC refuses when provider
 * usage exists, so reported usage always wins. */
export async function settleAiTestAudio(input: {
  supabaseUrl: string; serviceRoleKey: string; operationId: string; audioBytes: number; transcriptChars: number;
}): Promise<boolean> {
  if (!(input.audioBytes > 0)) return false;
  try {
    const body = await postAudioBudgetReceipt(input, 'rpc_ai_test_settle_audio_service', {
      p_operation_id: input.operationId, p_audio_bytes: input.audioBytes, p_transcript_chars: input.transcriptChars,
    });
    return body.operationId === input.operationId && body.settled === true && body.code === 'AI_AUDIO_SETTLED';
  } catch { return false; }
}

import { AI_CREDITS_UNAVAILABLE } from '../../../src/contracts/aiAvailability.ts';

/** Constructed only from the actual provider HTTP status, never provider text. */
export class GeminiCreditsUnavailableError extends Error {
  constructor() { super(AI_CREDITS_UNAVAILABLE); this.name = 'GeminiCreditsUnavailableError'; }
}

/** Provider-controlled block details must never become an error message or operator log. */
const SAFE_GEMINI_BLOCK_REASONS = new Set([
  'SAFETY', 'BLOCKLIST', 'PROHIBITED_CONTENT', 'SPII', 'OTHER', 'BLOCK_REASON_UNSPECIFIED',
]);

export class GeminiSafetyBlockedError extends Error {
  readonly blockReason: string;
  constructor(rawBlockReason: unknown) {
    super('GEMINI_SAFETY_BLOCKED');
    this.name = 'GeminiSafetyBlockedError';
    this.blockReason = typeof rawBlockReason === 'string' && SAFE_GEMINI_BLOCK_REASONS.has(rawBlockReason)
      ? rawBlockReason : 'UNKNOWN';
  }
}

/** Bounded provider stream. Only the top-level assistantMessage becomes UI text. */
function stringAt(input: string, start: number): { value: string; end: number; complete: boolean } {
  let value = '';
  for (let i = start + 1; i < input.length; i++) {
    const char = input[i];
    if (char === '"') return { value, end: i + 1, complete: true };
    if (char.charCodeAt(0) < 32) throw new Error('AI_STREAM_INVALID');
    if (char !== '\\') { value += char; continue; }
    if (++i >= input.length) return { value, end: input.length, complete: false };
    const escape = input[i];
    if (escape === 'u') {
      if (i + 4 >= input.length) return { value, end: input.length, complete: false };
      const digits = input.slice(i + 1, i + 5);
      if (!/^[a-f0-9]{4}$/i.test(digits)) throw new Error('AI_STREAM_INVALID');
      value += String.fromCharCode(parseInt(digits, 16)); i += 4;
    } else {
      const escapes: Record<string, string> = { '"': '"', '\\': '\\', '/': '/', b: '\b', f: '\f', n: '\n', r: '\r', t: '\t' };
      if (!(escape in escapes)) throw new Error('AI_STREAM_INVALID');
      value += escapes[escape];
    }
  }
  return { value, end: input.length, complete: false };
}

export function assistantPrefix(input: string): string {
  let depth = 0, key: string | null = null, expectingValue = false;
  for (let i = 0; i < input.length;) {
    const char = input[i];
    if (char === '"') {
      const parsed = stringAt(input, i);
      if (depth === 1 && expectingValue && key === 'assistantMessage') {
        let result = parsed.value;
        if (/[\uD800-\uDBFF]$/.test(result)) result = result.slice(0, -1);
        if (result.length > 1200 || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(result)) throw new Error('AI_STREAM_INVALID');
        return result;
      }
      if (!parsed.complete) return '';
      if (depth === 1 && !expectingValue) key = parsed.value;
      i = parsed.end; continue;
    }
    if (char === '{' || char === '[') depth++;
    else if (char === '}' || char === ']') depth--;
    else if (depth === 1 && char === ':') expectingValue = true;
    else if (depth === 1 && char === ',') { key = null; expectingValue = false; }
    if (depth < 0) throw new Error('AI_STREAM_INVALID');
    i++;
  }
  return '';
}

// The callers already declare the provider's own schema subset, with its UPPERCASE type
// names, so the adapter forwards types unchanged instead of rewriting them.

/** The live provider wire omits object-key and array-length bounds. The caller's
 * strict local decoder remains authoritative for unknown keys and item limits;
 * enum, nullable and numeric bounds are forwarded unchanged. */
const wireUnsupportedKeywords = new Set(['additionalProperties', 'maxItems', 'minItems']);

function providerSchema(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(providerSchema);
  if (!value || typeof value !== 'object') return value;
  const result: Record<string, unknown> = {};
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    if (wireUnsupportedKeywords.has(key)) continue;
    result[key] = providerSchema(item);
  }
  return result;
}

export function geminiRequestBody(raw: string): string {
  const payload = JSON.parse(raw);
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('AI_STREAM_INVALID');
  const generation = payload.generationConfig;
  if (!generation || typeof generation !== 'object' || Array.isArray(generation)) throw new Error('AI_STREAM_INVALID');
  const mime = generation.responseMimeType;
  const schema = generation.responseSchema;
  delete generation.temperature;
  delete generation.topP;
  delete generation.topK;
  delete generation.responseMimeType;
  delete generation.responseSchema;
  delete generation.responseFormat;
  generation.thinkingConfig = { thinkingLevel: 'low' };
  if (mime !== undefined || schema !== undefined) {
    if (mime !== 'application/json' || !schema || typeof schema !== 'object' || Array.isArray(schema)) throw new Error('AI_STREAM_INVALID');
    // Structured output travels in the provider's documented generateContent fields. The
    // earlier `responseFormat: { text: { mimeType, schema } }` wrapper is rejected by this
    // API with INVALID_ARGUMENT on `responseFormat.text.mimeType`, which is what broke every
    // turn after the function was redeployed onto it.
    generation.responseMimeType = mime;
    generation.responseSchema = providerSchema(schema);
  }
  return JSON.stringify(payload);
}

// Closed diagnostic vocabulary. Never emit raw provider messages, metadata, keys or task text.
const statuses = new Set(['INVALID_ARGUMENT', 'UNAUTHENTICATED', 'PERMISSION_DENIED', 'NOT_FOUND',
  'RESOURCE_EXHAUSTED', 'FAILED_PRECONDITION', 'UNAVAILABLE', 'INTERNAL', 'DEADLINE_EXCEEDED']);
const reasons = new Set(['API_KEY_INVALID', 'API_KEY_EXPIRED', 'API_KEY_SERVICE_BLOCKED',
  'API_KEY_HTTP_REFERRER_BLOCKED', 'API_KEY_IP_ADDRESS_BLOCKED', 'API_KEY_ANDROID_APP_BLOCKED',
  'API_KEY_IOS_APP_BLOCKED', 'SERVICE_DISABLED', 'BILLING_DISABLED', 'CONSUMER_INVALID',
  'ACCESS_TOKEN_EXPIRED', 'ACCESS_TOKEN_SCOPE_INSUFFICIENT']);
const fields: Record<string, string> = {
  'generation_config.response_format': 'RESPONSE_FORMAT', 'generationConfig.responseFormat': 'RESPONSE_FORMAT',
  'generation_config.response_schema': 'RESPONSE_SCHEMA', 'generationConfig.responseSchema': 'RESPONSE_SCHEMA',
  'generation_config.thinking_config.thinking_level': 'THINKING_LEVEL', 'generationConfig.thinkingConfig.thinkingLevel': 'THINKING_LEVEL',
  'generation_config.max_output_tokens': 'MAX_OUTPUT_TOKENS', 'generationConfig.maxOutputTokens': 'MAX_OUTPUT_TOKENS',
  // Structural paths only, still a closed list: an unlisted path stays UNKNOWN so no
  // upstream string can ever be printed. These narrow an INVALID_ARGUMENT to one node.
  'generation_config.response_format.text.schema': 'RESPONSE_FORMAT_SCHEMA',
  'generationConfig.responseFormat.text.schema': 'RESPONSE_FORMAT_SCHEMA',
  'generation_config.response_format.text.mime_type': 'RESPONSE_FORMAT_MIME',
  'generationConfig.responseFormat.text.mimeType': 'RESPONSE_FORMAT_MIME',
  'generation_config.response_format.text': 'RESPONSE_FORMAT_TEXT',
  'generationConfig.responseFormat.text': 'RESPONSE_FORMAT_TEXT',
  'generation_config.thinking_config': 'THINKING_CONFIG', 'generationConfig.thinkingConfig': 'THINKING_CONFIG',
  'generation_config': 'GENERATION_CONFIG', 'generationConfig': 'GENERATION_CONFIG',
  'system_instruction': 'SYSTEM_INSTRUCTION', 'systemInstruction': 'SYSTEM_INSTRUCTION',
  'contents': 'CONTENTS', 'model': 'MODEL', 'tools': 'TOOLS',
  'safety_settings': 'SAFETY_SETTINGS', 'safetySettings': 'SAFETY_SETTINGS',
};

export function geminiFailureDiagnostic(raw: unknown): { status: string; reason: string; field: string } {
  const value = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw as Record<string, unknown> : {};
  const e = value.error && typeof value.error === 'object' && !Array.isArray(value.error)
    ? value.error as Record<string, unknown> : {};
  const status = typeof e.status === 'string' && statuses.has(e.status) ? e.status : 'UNKNOWN';
  let reason = 'UNKNOWN', field = 'UNKNOWN';
  for (const rawDetail of Array.isArray(e.details) ? e.details.slice(0, 10) : []) {
    if (!rawDetail || typeof rawDetail !== 'object' || Array.isArray(rawDetail)) continue;
    const detail = rawDetail as Record<string, unknown>;
    if (typeof detail.reason === 'string' && reasons.has(detail.reason)) reason = detail.reason;
    for (const violation of Array.isArray(detail.fieldViolations) ? detail.fieldViolations.slice(0, 10) : []) {
      if (violation && typeof violation === 'object' && typeof violation.field === 'string'
        && Object.hasOwn(fields, violation.field)) field = fields[violation.field];
    }
  }
  return { status, reason, field };
}

/** Bounded inspection for operator logs; diagnostics cannot authorize a retry/refund. */
async function reportGeminiHttpFailure(response: Response, signal: AbortSignal): Promise<void> {
  let raw: unknown;
  const reader = response.body?.getReader();
  let rejectStopped: (error: Error) => void = () => {};
  const stopped = new Promise<never>((_resolve, reject) => { rejectStopped = reject; });
  const stop = () => rejectStopped(new Error('AI_STREAM_STOPPED'));
  try {
    if (!reader || signal.aborted) throw new Error('AI_STREAM_STOPPED');
    signal.addEventListener('abort', stop, { once: true });
    const decoder = new TextDecoder('utf-8', { fatal: true });
    let text = '', bytes = 0;
    while (true) {
      const part = await Promise.race([reader.read(), stopped]);
      if (signal.aborted) throw new Error('AI_STREAM_STOPPED');
      if (part.done) break;
      bytes += part.value.byteLength;
      if (bytes > 8192) throw new Error('AI_STREAM_TOO_LARGE');
      text += decoder.decode(part.value, { stream: true });
    }
    raw = JSON.parse(text + decoder.decode());
  } catch { /* Unknown details remain unknown; do not expose malformed upstream data. */ }
  finally { signal.removeEventListener('abort', stop); void reader?.cancel().catch(() => undefined); }
  const d = geminiFailureDiagnostic(raw);
  console.error('GEMINI_STREAM_HTTP_FAILED', response.status, d.status, d.reason, d.field);
}

/** Accounted input/output totals, never content. Output includes thinking. Cached
 * tokens are already part of input: this contract neither adds them nor discounts
 * them. A cache price adjustment requires its own verified pricing contract. */
export type GeminiUsage = { promptTokens: number; outputTokens: number; totalTokens: number };
export type GeminiUsageDetails = {
  usage: GeminiUsage | null;
  /** Raw provider prompt count, including its cached subset. */
  promptTokens: number | null;
  candidateTokens: number | null; thoughtTokens: number | null;
  toolUsePromptTokens: number | null; cachedPromptTokens: number | null;
  totalTokens: number | null;
};

const wholeCount = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value <= 10_000_000;

/** One decoder for generateContent and SSE, including failed provider attempts.
 * https://ai.google.dev/api/generate-content#UsageMetadata
 * total = prompt + tool-use prompt + candidates + thoughts. Missing optional
 * output/input counts are only zero when the reported total proves zero residual;
 * an unexplained residual is never guessed to be thinking. Invalid accounting
 * stays unknown and must not prevent delivery of an otherwise valid answer. */
export function decodeGeminiUsage(raw: unknown): GeminiUsageDetails {
  const metadata = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw as Record<string, unknown> : {};
  const count = (value: unknown): number | null => wholeCount(value) ? value : null;
  const promptTokens = count(metadata.promptTokenCount), candidateTokens = count(metadata.candidatesTokenCount);
  const totalTokens = count(metadata.totalTokenCount);
  let thoughtTokens = count(metadata.thoughtsTokenCount), toolUsePromptTokens = count(metadata.toolUsePromptTokenCount);
  const rawCached = count(metadata.cachedContentTokenCount);
  const cachedPromptTokens = rawCached !== null && promptTokens !== null && rawCached <= promptTokens ? rawCached : null;
  if (promptTokens !== null && candidateTokens !== null && totalTokens !== null) {
    // Only absence permits a proven zero. Explicit null/negative/string values are malformed.
    if (metadata.thoughtsTokenCount === undefined && (toolUsePromptTokens !== null || metadata.toolUsePromptTokenCount === undefined)
      && totalTokens === promptTokens + candidateTokens + (toolUsePromptTokens ?? 0)) thoughtTokens = 0;
    if (metadata.toolUsePromptTokenCount === undefined && (thoughtTokens !== null || metadata.thoughtsTokenCount === undefined)
      && totalTokens === promptTokens + candidateTokens + (thoughtTokens ?? 0)) toolUsePromptTokens = 0;
  }
  let usage: GeminiUsage | null = null;
  if (promptTokens !== null && candidateTokens !== null && totalTokens !== null
    && thoughtTokens !== null && toolUsePromptTokens !== null
    && totalTokens === promptTokens + toolUsePromptTokens + candidateTokens + thoughtTokens) {
    usage = { promptTokens: promptTokens + toolUsePromptTokens, outputTokens: candidateTokens + thoughtTokens, totalTokens };
  }
  return {
    usage,
    promptTokens, candidateTokens, thoughtTokens, toolUsePromptTokens, cachedPromptTokens, totalTokens,
  };
}

export function geminiUsage(raw: unknown): GeminiUsage | null {
  return decodeGeminiUsage(raw).usage;
}

export async function streamGeminiTask(input: {
  url: string; key: string; body: string; signal?: AbortSignal; onText: (delta: string) => void;
  onUsage?: (usage: GeminiUsage) => void;
  /** Count-only diagnostics, including unknown fields; never interpreted as a measured zero. */
  onUsageDetails?: (details: GeminiUsageDetails) => void;
  timeoutMs?: 30000;
}): Promise<string> {
  const controller = new AbortController();
  let rejectStopped: (error: Error) => void = () => {};
  const stoppedIO = new Promise<never>((_resolve, reject) => { rejectStopped = reject; });
  // Attach a handler even when cancellation precedes the first I/O operation.
  void stoppedIO.catch(() => undefined);
  const stop = () => { controller.abort(); rejectStopped(new Error('AI_STREAM_STOPPED')); };
  const timeout = setTimeout(stop, input.timeoutMs ?? 12000);
  input.signal?.addEventListener('abort', stop, { once: true });
  if (input.signal?.aborted) stop();
  let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
  let lastUsage = decodeGeminiUsage(undefined), receivedCompleteBody = false;
  try {
    if (controller.signal.aborted) throw new Error('AI_STREAM_STOPPED');
    const response = await Promise.race([fetch(input.url, { method: 'POST', redirect: 'error', signal: controller.signal,
      headers: { 'x-goog-api-key': input.key, 'Content-Type': 'application/json', Accept: 'text/event-stream' }, body: geminiRequestBody(input.body) }), stoppedIO]);
    if (!response.ok) {
      await reportGeminiHttpFailure(response, controller.signal);
      if (response.status === 402) throw new GeminiCreditsUnavailableError();
      throw new Error('AI_STREAM_UNAVAILABLE');
    }
    if (response.redirected || !response.body || !response.headers.get('content-type')?.includes('text/event-stream')) {
      void response.body?.cancel().catch(() => undefined); throw new Error('AI_STREAM_UNAVAILABLE');
    }
    reader = response.body.getReader();
    const decoder = new TextDecoder('utf-8', { fatal: true });
    let buffer = '', raw = '', emitted = '', total = 0, stopped = false;
    const event = (value: string) => {
      const lines = value.split('\n').filter(line => line.startsWith('data:')).map(line => line.slice(5).trim());
      if (!lines.length) return;
      const data = JSON.parse(lines.join('\n'));
      if (data.promptFeedback?.blockReason) throw new GeminiSafetyBlockedError(data.promptFeedback.blockReason);
      if (data.error) throw new Error('AI_STREAM_REJECTED');
      // Usage blocks are cumulative, not deltas. An explicit incomplete final block
      // supersedes older counts too: settling an earlier partial total undercharges.
      if (Object.hasOwn(data, 'usageMetadata')) lastUsage = decodeGeminiUsage(data.usageMetadata);
      if (!Array.isArray(data.candidates) || data.candidates.length > 1) throw new Error('AI_STREAM_INVALID');
      const candidate = data.candidates[0];
      if (!candidate) return;
      if (candidate.finishReason && ['SAFETY', 'BLOCKLIST', 'PROHIBITED_CONTENT', 'SPII', 'RECITATION'].includes(candidate.finishReason)) {
        throw new GeminiSafetyBlockedError(candidate.finishReason);
      }
      if (Array.isArray(candidate.safetyRatings) && candidate.safetyRatings.some((rating: any) => rating?.blocked === true))
        throw new GeminiSafetyBlockedError('SAFETY');
      if (candidate.finishReason && candidate.finishReason !== 'STOP') throw new Error('AI_STREAM_INCOMPLETE');
      if (candidate.finishReason === 'STOP') stopped = true;
      for (const part of candidate.content?.parts ?? []) {
        if (part.thought === true) continue;
        if (typeof part.text !== 'string') throw new Error('AI_STREAM_INVALID');
        raw += part.text;
        if (raw.length > 131072) throw new Error('AI_STREAM_TOO_LARGE');
        const safe = assistantPrefix(raw);
        if (!safe.startsWith(emitted)) throw new Error('AI_STREAM_INVALID');
        if (safe.length > emitted.length) {
          const delta = safe.slice(emitted.length); emitted = safe;
          if (controller.signal.aborted) throw new Error('AI_STREAM_STOPPED');
          input.onText(delta);
        }
      }
    };
    while (true) {
      const part = await Promise.race([reader.read(), stoppedIO]);
      if (controller.signal.aborted) throw new Error('AI_STREAM_STOPPED');
      if (part.done) break;
      total += part.value.byteLength;
      if (total > 524288) throw new Error('AI_STREAM_TOO_LARGE');
      buffer = (buffer + decoder.decode(part.value, { stream: true })).replace(/\r\n/g, '\n');
      let boundary: number;
      while ((boundary = buffer.indexOf('\n\n')) !== -1) { event(buffer.slice(0, boundary)); buffer = buffer.slice(boundary + 2); }
      if (buffer.length > 131072) throw new Error('AI_STREAM_TOO_LARGE');
    }
    buffer += decoder.decode();
    if (buffer.trim()) event(buffer);
    receivedCompleteBody = true;
    if (!stopped || typeof JSON.parse(raw).assistantMessage !== 'string' || JSON.parse(raw).assistantMessage !== emitted) throw new Error('AI_STREAM_INCOMPLETE');
    return raw;
  } finally {
    // A fully received provider response can have invalid application JSON but still
    // consume known tokens. An interrupted body must not settle an intermediate total.
    if (receivedCompleteBody) {
      if (input.onUsageDetails) { try { input.onUsageDetails(lastUsage); } catch { /* accounting never breaks delivery */ } }
      if (lastUsage.usage && input.onUsage) { try { input.onUsage(lastUsage.usage); } catch { /* accounting never breaks delivery */ } }
    }
    clearTimeout(timeout); input.signal?.removeEventListener('abort', stop); controller.abort();
    void reader?.cancel().catch(() => undefined);
  }
}

// Read-only, version-fenced navigation of the canonical taxonomy. The model can
// reach any branch; a response page is never described as the whole catalog.
import { normalizedClassificationIdentity } from './classificationEngine.mjs';

const record = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const uuid = v => typeof v === 'string' && /^[a-f\d]{8}-[a-f\d]{4}-[1-8][a-f\d]{3}-[89ab][a-f\d]{3}-[a-f\d]{12}$/i.test(v);
const bytes = v => new TextEncoder().encode(JSON.stringify(v)).byteLength;
const fingerprint = v => typeof v === 'string' && /^[a-f\d]{32}$/.test(v);
const operations = new Set(['META','SEARCH','EXACT','ROOTS','CHILDREN','SIBLINGS','ANCESTORS','RESOLVE']);
const fail = code => { throw new Error('CLASSIFICATION_EXPLORER_' + code); };
const label = value => normalizedClassificationIdentity(value) !== null;
const queryKey = query => JSON.stringify(Object.fromEntries(Object.entries(query).sort(([a],[b]) => a.localeCompare(b))
  .map(([key,value]) => [key,key === 'categoryIds' ? [...value].sort() : value])));

export const taxonomyToolDeclaration = Object.freeze({
  name: 'taxonomy_catalog',
  description: 'Read the CURRENT server catalog. SEARCH searches across the whole eligible catalog; use several meaningful terms/synonyms when needed. ROOTS, CHILDREN, SIBLINGS and ANCESTORS explore its structure. RESOLVE reads real IDs. Results are pages, never the whole tree. Follow nextCursor with the SAME operation, filters and service. Search the actual service in scope ALL before proposing a new branch. No write, Save, matching or notification authority.',
  parameters: { type: 'OBJECT', required: ['operation'], properties: {
    operation: { type: 'STRING', enum: ['SEARCH','ROOTS','CHILDREN','SIBLINGS','ANCESTORS','RESOLVE'] },
    text: { type: 'STRING', description: 'SEARCH query, 1–256 characters (e.g. 3D); use useful job/object terms, not the whole conversation.' },
    service: { type: 'STRING', description: 'Exact proposed service name whose meaning this SEARCH investigates (3–120 characters).' },
    scope: { type: 'STRING', enum: ['ALL','REMOTE','ON_SITE'], description: 'Default ALL. Search ALL for novelty; service delivery is a separate question.' },
    categoryId: { type: 'STRING', description: 'Existing UUID for CHILDREN, SIBLINGS or ANCESTORS.' },
    categoryIds: { type: 'ARRAY', items: { type: 'STRING' }, description: 'Existing UUIDs for RESOLVE.' },
    cursor: { type: 'STRING', description: 'The exact nextCursor previously returned for this query.' },
  } },
});

export async function createClassificationExplorer(rpc, options = {}) {
  if (typeof rpc !== 'function') fail('INVALID_RPC');
  const { signal, seedServices = [], seedCategoryIds = [], pageSize = 32,
    maxPageBytes = 524288, maxEvidenceBytes = 2097152, maxQueries = 128 } = options;
  if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > 100 ||
      !Number.isInteger(maxQueries) || maxQueries < 2 ||
      !Number.isInteger(maxPageBytes) || maxPageBytes < 1024 ||
      !Number.isInteger(maxEvidenceBytes) || maxEvidenceBytes < maxPageBytes) fail('INVALID_LIMITS');
  let version = null, digest = null, receivedBytes = 0, queryCount = 0, invalid = false;
  const nodes = new Map(), cache = new Map(), inFlight = new Map(), issuedCursors = new Map(), searched = new Set();
  const identities = new Map(), initialPages = [];
  const modelPage = answer => ({ ...answer, items: answer.items.map(({ path, pathIds, ...item }) => item) });
  const active = () => { if (signal?.aborted) fail('CANCELLED'); if (invalid) fail('INCOMPLETE'); };
  function validateNode(row) {
    if (!record(row) || !uuid(row.categoryId) || !label(row.label) ||
        !(row.parentId === null || uuid(row.parentId)) || !Array.isArray(row.aliases) || !row.aliases.every(label) ||
        !Array.isArray(row.modes) || !row.modes.length || row.modes.some(m => !['REMOTE','ON_SITE'].includes(m)) ||
        !Array.isArray(row.path) || !row.path.length || !row.path.every(label) ||
        !Array.isArray(row.pathIds) || row.pathIds.length !== row.path.length || !row.pathIds.every(uuid) ||
        new Set(row.pathIds).size !== row.pathIds.length || row.pathIds.at(-1) !== row.categoryId ||
        row.path.at(-1) !== row.label || (row.pathIds.length > 1 ? row.pathIds.at(-2) !== row.parentId : row.parentId !== null) ||
        typeof row.isLeaf !== 'boolean') fail('INVALID_NODE');
    const node = { id: row.categoryId, label: row.label, parentId: row.parentId,
      aliases: row.aliases.slice(), modes: row.modes.slice(), path: row.path.slice(), isLeaf: row.isLeaf };
    const prior = nodes.get(node.id);
    if (prior && JSON.stringify(prior) !== JSON.stringify(node)) fail('CONFLICTING_NODE');
    nodes.set(node.id, node);
    return node;
  }
  async function query(raw, { fresh = false } = {}) {
    active();
    if (!record(raw) || !operations.has(raw.operation)) fail('INVALID_QUERY');
    const q = { ...raw, scope: raw.scope ?? 'ALL', limit: pageSize };
    if (!['ALL','REMOTE','ON_SITE'].includes(q.scope)) fail('INVALID_SCOPE');
    const service = q.service; delete q.service;
    if (Object.keys(q).some(k => !['operation','scope','limit','text','categoryId','categoryIds','cursor'].includes(k))) fail('INVALID_QUERY');
    if (['SEARCH','EXACT'].includes(q.operation) && (typeof q.text !== 'string' || !q.text.trim() || q.text.length > 256 || /[\u0000-\u001f]/.test(q.text))) fail('INVALID_TEXT');
    if (service !== undefined && !label(service)) fail('INVALID_SERVICE');
    if (['CHILDREN','SIBLINGS','ANCESTORS'].includes(q.operation) && !uuid(q.categoryId)) fail('INVALID_ID');
    if (q.operation === 'RESOLVE' && (!Array.isArray(q.categoryIds) || q.categoryIds.length > 100 || !q.categoryIds.every(uuid))) fail('INVALID_IDS');
    const base = { ...q }; delete base.cursor;
    const key = queryKey(base), cacheKey = queryKey(q);
    if (q.cursor != null && (typeof q.cursor !== 'string' || !issuedCursors.get(q.cursor)?.has(key))) fail('UNKNOWN_CURSOR');
    let answer = fresh ? undefined : cache.get(cacheKey);
    if (!answer) {
      // A shared request belongs to this explorer's single META-fenced snapshot.
      // Fresh checks never join an older request: each is a new end-of-research barrier.
      let pending = fresh ? undefined : inFlight.get(cacheKey);
      if (!pending) {
        if (++queryCount > maxQueries) { invalid = true; fail('QUERY_BUDGET'); }
        pending = (async () => {
          try {
            const received = await rpc('rpc_taxonomy_query_catalog_service', { p_query: {
              ...q, ...(version !== null ? { catalogVersion: version, catalogFingerprint: digest } : {}),
            } });
            active();
            const size = bytes(received); receivedBytes += size;
            if (size > maxPageBytes || receivedBytes > maxEvidenceBytes) fail('EVIDENCE_BUDGET');
            if (!record(received) || received.schemaVersion !== 'TAXONOMY_CATALOG_QUERY_V1' || received.action !== 'CATALOG_QUERY' ||
                received.operation !== q.operation || received.scope !== q.scope ||
                !Number.isSafeInteger(received.catalogVersion) || received.catalogVersion < 1 || !fingerprint(received.catalogFingerprint) ||
                !Array.isArray(received.items) || received.items.length > pageSize || received.count !== received.items.length ||
                !['classificationAuthority','capabilityAuthority','notificationAuthority'].every(k => received[k] === 'NONE') ||
                !(received.nextCursor === null || typeof received.nextCursor === 'string' && received.nextCursor.length > 0 && received.nextCursor.length < 16384)) fail('INVALID_PAGE');
            if (version !== null && (received.catalogVersion !== version || received.catalogFingerprint !== digest)) fail('STALE');
            version = received.catalogVersion; digest = received.catalogFingerprint;
            received.items.forEach(validateNode);
            if (received.nextCursor !== null) {
              if (received.nextCursor === q.cursor) fail('REPEATED_CURSOR');
              const keys = issuedCursors.get(received.nextCursor) ?? new Map();
              if (keys.has(key) && keys.get(key) !== cacheKey) fail('REPEATED_CURSOR');
              keys.set(key,cacheKey); issuedCursors.set(received.nextCursor, keys);
            }
            cache.set(cacheKey, received);
            return received;
          } catch (error) { invalid = true; throw error; }
        })();
        if (!fresh) inFlight.set(cacheKey, pending);
      }
      try { answer = await pending; }
      finally { if (inFlight.get(cacheKey) === pending) inFlight.delete(cacheKey); }
      // A peer may have invalidated the shared snapshot before this waiter resumes.
      active();
    }
    if (q.operation === 'SEARCH' && q.scope === 'ALL' && answer.nextCursor === null && label(service ?? q.text))
      searched.add(normalizedClassificationIdentity(service ?? q.text));
    return answer;
  }
  async function allExact(service) {
    const key = normalizedClassificationIdentity(service);
    if (!key || identities.has(key)) return;
    const ids = new Set(); let cursor;
    do {
      const page = await query({ operation: 'EXACT', text: service, scope: 'ALL', ...(cursor ? { cursor } : {}) });
      for (const node of page.items) ids.add(node.categoryId);
      cursor = page.nextCursor;
    } while (cursor !== null);
    identities.set(key, [...ids]);
  }
  async function allResolved(categoryIds) {
    const pages = []; let cursor;
    do {
      const page = await query({ operation: 'RESOLVE', categoryIds, ...(cursor ? { cursor } : {}) });
      pages.push(page); cursor = page.nextCursor;
    } while (cursor !== null);
    return pages;
  }
  async function independent(jobs) {
    const results = new Array(jobs.length); let next = 0;
    // Bound RPC concurrency, not the number of catalog nodes or cursor pages.
    await Promise.all(Array.from({ length: Math.min(4,jobs.length) }, async () => {
      while (next < jobs.length) {
        active(); const index = next++;
        results[index] = await jobs[index]();
      }
    }));
    active();
    return results;
  }
  await query({ operation: 'META' });
  const seeds = [...new Set(seedServices.filter(label).map(s => s.trim()))].slice(0, 24);
  const seedIds = [...new Set(seedCategoryIds.filter(uuid))].slice(0, 100);
  const [roots, resolved, ...seedPages] = await independent([
    () => query({ operation: 'ROOTS' }),
    () => seedIds.length ? allResolved(seedIds) : [],
    ...seeds.map(service => () => query({ operation: 'SEARCH', text: service, service })),
  ]);
  initialPages.push({ query: { operation: 'ROOTS', scope: 'ALL' }, page: roots },
    ...seedPages.map((page,index) => ({ query: { operation: 'SEARCH', scope: 'ALL', text: seeds[index], service: seeds[index] }, page })),
    ...resolved.map(page => ({ query: { operation: 'RESOLVE', scope: 'ALL', categoryIds: seedIds }, page })));

  const snapshot = () => ({ catalogVersion: version, catalogFingerprint: digest, categories: [...nodes.values()],
    navigation: { kind: 'SERVER_QUERIES', identityChecks: [...identities].map(([service, categoryIds]) => ({ service, categoryIds })),
      searchedServices: [...searched] } });
  return {
    get catalogVersion() { return version; },
    get catalogFingerprint() { return digest; },
    get queryCount() { return queryCount; },
    get evidenceBytes() { return receivedBytes; },
    canTryDirectReply() {
      // Eligibility only, never a binding or proof of global uniqueness. A
      // fresh verify() still checks every identity and catalog version after
      // inference. New/unknown services start with the full navigation tools.
      active();
      return seeds.length > 0 && seeds.every(service => {
        const identity = normalizedClassificationIdentity(service);
        return [...nodes.values()].filter(node => [node.label, ...node.aliases]
          .some(value => normalizedClassificationIdentity(value) === identity)).length === 1;
      });
    },
    prompt(phase = 'research') {
      active();
      if (!['direct','research'].includes(phase)) fail('INVALID_PHASE');
      const initialNodes = new Map(initialPages.flatMap(({page}) => page.items.map(row => [row.categoryId,row])));
      if (phase === 'direct') {
        const keys = new Set(seeds.map(normalizedClassificationIdentity));
        let directCategories = keys.size > 0
          ? [...initialNodes.values()].filter(row => [row.label,...row.aliases].some(value => keys.has(normalizedClassificationIdentity(value))))
          : [...initialNodes.values()];
        if (!directCategories.length) directCategories = [...initialNodes.values()];
        return JSON.stringify({ catalogVersion: version, catalogFingerprint: digest, complete: false,
          classificationAuthority: 'NONE', categories: directCategories
            .map(({categoryId,label,aliases,modes}) => ({categoryId,label,aliases,modes})) });
      }
      return JSON.stringify({ catalogVersion: version, catalogFingerprint: digest, complete: false,
        catalogAccess: 'WHOLE_CURRENT_CATALOG_VIA_READ_ONLY_TOOLS', classificationAuthority: 'NONE',
        categories: [...initialNodes.values()].map(({path,pathIds,...row}) => row),
        pages: initialPages.map(({query,page}) => ({ query, count: page.count, nextCursor: page.nextCursor,
          categoryIds: page.items.map(row => row.categoryId) })) });
    },
    async execute(args, context = {}) {
      if (context.signal?.aborted) fail('CANCELLED');
      if (!record(args) || !taxonomyToolDeclaration.parameters.properties.operation.enum.includes(args.operation)) fail('INVALID_TOOL');
      return modelPage(await query(args));
    },
    async verify(raw, { services = [], categoryIds = [] } = {}) {
      // Provider fields remain untrusted. Global exact/alias checks are performed
      // by the server, including collisions outside the pages the model explored.
      active();
      let proposals = [];
      if (record(raw) && typeof raw.classificationShadowJson === 'string' && bytes(raw.classificationShadowJson) <= 32768) {
        try { const value = JSON.parse(raw.classificationShadowJson); if (Array.isArray(value) && value.length <= 24) proposals = value.filter(record); } catch { /* strict inspector handles malformed metadata */ }
      }
      const names = [...new Set([...services, ...proposals.map(p => p.service)].filter(label))];
      if (names.length > 48) fail('INVALID_SERVICE_BATCH');
      const ids = [...new Set([...categoryIds, ...proposals.flatMap(p => [p.categoryId,p.parentId])].filter(uuid))];
      if (ids.length > 100) fail('INVALID_ID_BATCH');
      await independent([
        ...(ids.length ? [() => allResolved(ids)] : []),
        ...names.map(name => () => allExact(name)),
      ]);
      // Recheck freshness after inference, including alias-only updates. A stale
      // result can never turn into a captured classification hint.
      await query({ operation: 'META' }, { fresh: true });
      return snapshot();
    },
  };
}

import { measureAiPhase } from './aiPhaseTiming.mjs';
import {
  GeminiCreditsUnavailableError, GeminiSafetyBlockedError,
  geminiFailureDiagnostic, geminiRequestBody, decodeGeminiUsage,
  type GeminiUsage,
} from './geminiTaskStream.ts';

type JsonObject = Record<string, unknown>;
export type GeminiReadOnlyTool = {
  declaration: JsonObject & { name: string };
  readOnly: true;
  /** Validate the complete domain argument contract here, before performing a read. */
  execute: (args: JsonObject, context: { signal: AbortSignal; callId?: string; round: number }) => Promise<JsonObject>;
};
export type GeminiToolLimits = {
  maxToolRounds: number;
  maxToolCalls: number;
  maxCallsPerRound: number;
  maxRequestBytes: number;
  maxResponseBytes: number;
  maxToolResultBytes: number;
  maxOutputTokens: number;
  maxTurnOutputTokens: number;
  timeoutMs: number;
  accountingTimeoutMs: number;
};
export type GeminiAttemptAdmission = {
  attempt: number; phase: 'TOOLS' | 'FINAL'; requestBytes: number;
  maxOutputTokens: number; signal: AbortSignal;
};
export type GeminiAttemptReceipt = { reservationId: string };
export type GeminiAttemptReport = Omit<GeminiAttemptAdmission, 'signal'> & GeminiAttemptReceipt & {
  dispatched: boolean; outcome: 'SUCCEEDED' | 'FAILED'; httpStatus: number | null;
  /** Null is unknown, never a measured zero. Counts include failed provider responses. */
  usage: GeminiUsage | null; cumulativeUsage: GeminiUsage;
  /** This attempt can be settled even when an earlier attempt still has an unknown hold. */
  attemptUsageComplete: boolean;
  /** Cumulative completeness across all dispatched attempts. */
  usageComplete: boolean;
  /** Raw breakdown; this transport's usage.outputTokens includes candidates AND thinking. */
  candidateTokens: number | null; thoughtTokens: number | null;
  /** Cached is a subset of prompt input, not additional usage. Missing stays unknown. */
  cachedPromptTokens: number | null; toolUsePromptTokens: number | null;
  errorCode: string | null;
};
export type GeminiToolConversationInput<T = string> = {
  url: string; key: string; body: string; signal?: AbortSignal;
  tools: readonly GeminiReadOnlyTool[];
  limits?: Partial<GeminiToolLimits>;
  /** Combined mode avoids a paid 'done' round. Split mode is explicit, never a retry fallback. */
  mode?: 'COMBINED' | 'SEPARATE';
  parseFinal?: (raw: string) => T;
  /** Try current supplied evidence without a tool round first. The caller verifies the
   * complete effective domain state; false permits research within this SAME budget.
   * Runs after accounting and under the turn deadline. Exceptions never trigger retry. */
  directFirst?: {
    accept: (raw: string) => Promise<boolean>;
    /** Server-owned first-phase instructions only; history, schema and budgets stay shared. */
    systemParts?: readonly { text: string }[];
  };
  /** Durably reserve before EVERY attempt. Use deterministic operation ids so an admission
   * whose acknowledgement is lost at cancellation can be recovered without another charge. */
  beforeAttempt: (attempt: GeminiAttemptAdmission) => Promise<GeminiAttemptReceipt>;
  /** Must acknowledge accounting before another paid attempt. Never retried by this helper. */
  onAttempt: (report: GeminiAttemptReport) => Promise<void>;
};
export type GeminiToolConversationResult<T> = {
  value: T; raw: string; usage: GeminiUsage; usageComplete: boolean;
  accountingComplete: boolean; attempts: number; toolCalls: number;
};

const defaults: GeminiToolLimits = {
  maxToolRounds: 3, maxToolCalls: 24, maxCallsPerRound: 12,
  maxRequestBytes: 262144, maxResponseBytes: 524288, maxToolResultBytes: 65536,
  maxOutputTokens: 8192, maxTurnOutputTokens: 32768,
  timeoutMs: 35000, accountingTimeoutMs: 5000,
};
const object = (value: unknown): value is JsonObject => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const count = (value: unknown): value is number => typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value <= 10_000_000;
function fail(code: string): never { throw new Error(code); }
const bytes = (text: string) => new TextEncoder().encode(text).byteLength;
const safeError = (error: unknown): string => error instanceof GeminiSafetyBlockedError ? 'GEMINI_SAFETY_BLOCKED'
  : error instanceof GeminiCreditsUnavailableError ? 'AI_CREDITS_UNAVAILABLE'
  : error instanceof Error && /^AI_TOOL_[A-Z_]+$/.test(error.message) ? error.message : 'AI_TOOL_UNAVAILABLE';
const addUsage = (sum: GeminiUsage, value: GeminiUsage) => {
  sum.promptTokens += value.promptTokens; sum.outputTokens += value.outputTokens; sum.totalTokens += value.totalTokens;
};

/** Manual generateContent loop: only allowlisted read callbacks; no SDK auto execution/retry.
 * Gemini 3 supports function calls OR the structured response in the same request:
 * https://ai.google.dev/gemini-api/docs/generate-content/function-calling#function-calling-with-structured-output
 * Full model content (including opaque thoughtSignature parts) is returned unchanged.
 * Domain JSON/schema validation and server-owned Save authority remain with the caller.
 */
export async function generateGeminiToolConversation<T = string>(input: GeminiToolConversationInput<T>): Promise<GeminiToolConversationResult<T>> {
  const limits = { ...defaults, ...input.limits };
  for (const [key, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < (key === 'maxToolRounds' || key === 'maxToolCalls' ? 0 : 1)) fail('AI_TOOL_INVALID_CONFIG');
  }
  if (typeof input.beforeAttempt !== 'function' || typeof input.onAttempt !== 'function') fail('AI_TOOL_INVALID_CONFIG');
  if (input.mode !== undefined && input.mode !== 'COMBINED' && input.mode !== 'SEPARATE') fail('AI_TOOL_INVALID_CONFIG');
  const toolMap = new Map<string, GeminiReadOnlyTool>();
  for (const tool of input.tools) {
    const name = tool?.declaration?.name;
    if (tool.readOnly !== true || typeof tool.execute !== 'function' || typeof name !== 'string'
      || !/^[a-zA-Z_][a-zA-Z0-9_.:-]{0,63}$/.test(name) || toolMap.has(name)) fail('AI_TOOL_INVALID_CONFIG');
    toolMap.set(name, tool);
  }
  if (input.directFirst !== undefined && (!object(input.directFirst)
    || typeof input.directFirst.accept !== 'function' || input.mode === 'SEPARATE' || toolMap.size === 0)) fail('AI_TOOL_INVALID_CONFIG');
  const firstParts = input.directFirst?.systemParts;
  if (firstParts !== undefined && (!Array.isArray(firstParts) || !firstParts.length
    || firstParts.some(part => !object(part) || Object.keys(part).length !== 1
      || typeof part.text !== 'string' || !part.text.trim()))) fail('AI_TOOL_INVALID_CONFIG');
  // Snapshot caller-owned data before any await; a later mutation cannot alter a request.
  const directSystemParts = firstParts?.map(part => ({ text: part.text }));
  let base: JsonObject;
  try { base = JSON.parse(geminiRequestBody(input.body)); } catch { return fail('AI_TOOL_INVALID_CONFIG'); }
  if (!Array.isArray(base.contents) || !base.contents.length || !object(base.generationConfig)
    || base.generationConfig.responseMimeType !== 'application/json' || !object(base.generationConfig.responseSchema)) fail('AI_TOOL_INVALID_CONFIG');
  // Do not allow undeclared built-in/action tools to hitch a ride in the caller's body.
  delete base.tools; delete base.toolConfig;
  const contents = [...base.contents as unknown[]];
  const originalGeneration = base.generationConfig as JsonObject;
  if (originalGeneration.candidateCount !== undefined && originalGeneration.candidateCount !== 1) fail('AI_TOOL_INVALID_CONFIG');
  const configuredCap = originalGeneration.maxOutputTokens;
  if (configuredCap !== undefined && (!count(configuredCap) || configuredCap === 0)) fail('AI_TOOL_INVALID_CONFIG');
  const perCallCap = Math.min(limits.maxOutputTokens, typeof configuredCap === 'number' ? configuredCap : limits.maxOutputTokens);
  const controller = new AbortController();
  let rejectStopped: (error: Error) => void = () => {};
  const stopped = new Promise<never>((_resolve, reject) => { rejectStopped = reject; });
  void stopped.catch(() => undefined);
  const stop = () => { controller.abort(); rejectStopped(new Error('AI_TOOL_STOPPED')); };
  const check = () => { if (controller.signal.aborted) fail('AI_TOOL_STOPPED'); };
  const wait = <V>(operation: Promise<V>): Promise<V> => Promise.race([operation, stopped]);
  const timeout = setTimeout(stop, limits.timeoutMs);
  input.signal?.addEventListener('abort', stop, { once: true });
  if (input.signal?.aborted) stop();
  let attempts = 0, toolCalls = 0, rounds = 0, spentOutputTokens = 0;
  let usageComplete = true, accountingComplete = true;
  const usage: GeminiUsage = { promptTokens: 0, outputTokens: 0, totalTokens: 0 };
  const seenIds = new Set<string>();
  let forceFinal = toolMap.size === 0;

  const account = async (report: GeminiAttemptReport): Promise<void> => {
    // Settlement also runs after cancellation; the stopped IO promise must not skip it.
    let accountingTimer: ReturnType<typeof setTimeout> | undefined;
    try {
      await Promise.race([Promise.resolve().then(() => input.onAttempt(report)), new Promise<never>((_resolve, reject) => {
        accountingTimer = setTimeout(() => reject(new Error('AI_TOOL_ACCOUNTING_FAILED')), limits.accountingTimeoutMs);
      })]);
    } finally { clearTimeout(accountingTimer); }
  };

  const readBody = async (response: Response): Promise<unknown> => {
    const reader = response.body?.getReader();
    if (!reader) return fail('AI_TOOL_INVALID_RESPONSE');
    const decoder = new TextDecoder('utf-8', { fatal: true });
    let raw = '', size = 0;
    try {
      while (true) {
        const chunk = await wait(reader.read()); check();
        if (chunk.done) break;
        size += chunk.value.byteLength;
        if (size > limits.maxResponseBytes) fail('AI_TOOL_RESPONSE_TOO_LARGE');
        raw += decoder.decode(chunk.value, { stream: true });
      }
      try { return JSON.parse(raw + decoder.decode()); } catch { return fail('AI_TOOL_INVALID_RESPONSE'); }
    } finally { void reader.cancel().catch(() => undefined); }
  };

  try {
    // Each tool round requires a provider attempt; the last attempt is always final-only.
    while (attempts <= limits.maxToolRounds) {
      check();
      const directAttempt = input.directFirst !== undefined && attempts === 0;
      // The direct attempt consumes one of the original slots, not an extra paid call.
      const withTools = !directAttempt && !forceFinal && attempts < limits.maxToolRounds
        && rounds < limits.maxToolRounds && toolCalls < limits.maxToolCalls;
      const phase = withTools ? 'TOOLS' as const : 'FINAL' as const;
      const maxOutputTokens = Math.min(perCallCap, limits.maxTurnOutputTokens - spentOutputTokens);
      if (maxOutputTokens <= 0) fail('AI_TOOL_TOKEN_BUDGET');
      const generation: JsonObject = { ...originalGeneration, maxOutputTokens, candidateCount: 1 };
      if (withTools && input.mode === 'SEPARATE') {
        delete generation.responseMimeType; delete generation.responseSchema;
      }
      const request: JsonObject = { ...base, contents, generationConfig: generation };
      if (withTools) {
        request.tools = [{ functionDeclarations: [...toolMap.values()].map(tool => tool.declaration) }];
        request.toolConfig = { functionCallingConfig: { mode: input.mode === 'SEPARATE' ? 'AUTO' : 'VALIDATED' } };
      } else if (directAttempt) {
        const system = object(base.systemInstruction) ? base.systemInstruction : {};
        request.systemInstruction = { ...system, parts: [
          ...(directSystemParts ?? (Array.isArray(system.parts) ? system.parts : [])),
          { text: 'First try to return the complete required JSON using the supplied CURRENT server evidence. '
            + 'No tools are offered in this first attempt. Keep useful user facts and partial answers; '
            + 'mark unresolved classification as NEEDS_REVIEW or ask for missing user information. '
            + 'Never invent category IDs, modes, consent, completed research or successful writes. '
            + 'The server will verify the result and may provide catalog tools if research is still needed.' },
        ] };
      } else if (toolMap.size > 0) {
        const system = object(base.systemInstruction) ? base.systemInstruction : {};
        request.systemInstruction = { ...system, parts: [
          ...(Array.isArray(system.parts) ? system.parts : []),
          { text: 'Catalog research for this turn is closed. Return only the required final JSON schema now. '
            + 'Keep useful user facts and partial answers. For unresolved classification use NEEDS_REVIEW; '
            + 'incomplete research is not evidence that a category is absent. Do not invent missing tool results, '
            + 'category IDs, successful writes or resolved identity. No further tool calls are available.' },
        ] };
      }
      const body = JSON.stringify(request), requestBytes = bytes(body);
      if (requestBytes > limits.maxRequestBytes) fail('AI_TOOL_REQUEST_TOO_LARGE');
      const admission: GeminiAttemptAdmission = { attempt: attempts + 1, phase, requestBytes, maxOutputTokens, signal: controller.signal };
      let knownReceipt: GeminiAttemptReceipt | undefined;
      try {
        await measureAiPhase('ADMISSION', () => wait(input.beforeAttempt(admission).then(value => { knownReceipt = value; })));
      } catch {
        // If the receipt is already known, cancellation must not leave a known undispatched
        // hold behind. An unresolved/lost acknowledgement remains the caller's durable recovery.
        if (object(knownReceipt) && typeof knownReceipt.reservationId === 'string' && knownReceipt.reservationId.trim()) {
          try { await account({ ...admission, reservationId: knownReceipt.reservationId, dispatched: false,
            outcome: 'FAILED', httpStatus: null, usage: null, cumulativeUsage: { ...usage }, usageComplete,
            attemptUsageComplete: false, candidateTokens: null, thoughtTokens: null,
            cachedPromptTokens: null, toolUsePromptTokens: null, errorCode: 'AI_TOOL_STOPPED' }); }
          catch { return fail('AI_TOOL_ACCOUNTING_FAILED'); }
        }
        if (controller.signal.aborted) return fail('AI_TOOL_STOPPED');
        return fail('AI_TOOL_ADMISSION_FAILED');
      }
      const receipt = knownReceipt;
      if (!object(receipt) || typeof receipt.reservationId !== 'string' || !receipt.reservationId.trim()) fail('AI_TOOL_ADMISSION_FAILED');
      let dispatched = false, outcome: 'SUCCEEDED' | 'FAILED' = 'FAILED', httpStatus: number | null = null;
      let currentUsage: GeminiUsage | null = null, currentCandidates: number | null = null, currentThoughts: number | null = null, errorCode: string | null = null;
      let currentCached: number | null = null, currentToolPrompt: number | null = null;
      let modelContent: JsonObject | undefined, calls: JsonObject[] = [], finalRaw: string | undefined, value: T | undefined;
      try {
        check(); dispatched = true; attempts++;
        const { response, payload } = await measureAiPhase('PROVIDER', async () => {
          const response = await wait(fetch(input.url, { method: 'POST', redirect: 'error', signal: controller.signal,
            headers: { 'x-goog-api-key': input.key, 'Content-Type': 'application/json', Accept: 'application/json' }, body }));
          httpStatus = response.status;
          let payload: unknown;
          try { payload = await readBody(response); } catch (error) { if (response.ok) throw error; }
          return { response, payload };
        });
        check();
        if (object(payload)) {
          const reported = decodeGeminiUsage(payload.usageMetadata);
          currentUsage = reported.usage;
          currentCandidates = reported.candidateTokens; currentThoughts = reported.thoughtTokens;
          currentCached = reported.cachedPromptTokens; currentToolPrompt = reported.toolUsePromptTokens;
        }
        if (!response.ok) {
          const diagnostic = geminiFailureDiagnostic(payload);
          console.error('GEMINI_TOOLS_HTTP_FAILED', response.status, diagnostic.status, diagnostic.reason, diagnostic.field);
          if (response.status === 402) throw new GeminiCreditsUnavailableError();
          fail('AI_TOOL_UNAVAILABLE');
        }
        if (!object(payload)) fail('AI_TOOL_INVALID_RESPONSE');
        const feedback = payload.promptFeedback;
        if (object(feedback) && feedback.blockReason) throw new GeminiSafetyBlockedError(feedback.blockReason);
        const candidates = payload.candidates;
        if (!Array.isArray(candidates) || candidates.length !== 1 || !object(candidates[0])) fail('AI_TOOL_INVALID_RESPONSE');
        const candidate = candidates[0];
        if (['SAFETY', 'BLOCKLIST', 'PROHIBITED_CONTENT', 'SPII', 'RECITATION'].includes(String(candidate.finishReason))) throw new GeminiSafetyBlockedError(candidate.finishReason);
        if (candidate.finishReason !== 'STOP') fail('AI_TOOL_INCOMPLETE');
        if (Array.isArray(candidate.safetyRatings) && candidate.safetyRatings.some(rating => object(rating) && rating.blocked === true)) throw new GeminiSafetyBlockedError('SAFETY');
        const content = candidate.content;
        if (!object(content) || content.role !== 'model' || !Array.isArray(content.parts) || !content.parts.length) fail('AI_TOOL_INVALID_RESPONSE');
        modelContent = content;
        const texts: string[] = [];
        for (const part of content.parts) {
          if (!object(part)) fail('AI_TOOL_INVALID_RESPONSE');
          if (['inlineData', 'fileData', 'executableCode', 'codeExecutionResult', 'functionResponse'].some(key => key in part)) fail('AI_TOOL_INVALID_RESPONSE');
          if (object(part.functionCall)) calls.push(part.functionCall);
          else if (part.thought === true) continue;
          else if (typeof part.text === 'string') texts.push(part.text);
          else if (!part.thoughtSignature) fail('AI_TOOL_INVALID_RESPONSE');
        }
        if (calls.length) {
          if (!withTools) fail('AI_TOOL_UNEXPECTED_CALL');
          if (calls.length > limits.maxCallsPerRound || toolCalls + calls.length > limits.maxToolCalls) fail('AI_TOOL_CALL_BUDGET');
          // Validate the WHOLE batch before the first callback can read anything.
          const batchIds = new Set<string>();
          for (const call of calls) {
            if (typeof call.name !== 'string' || !toolMap.has(call.name) || !object(call.args)) fail('AI_TOOL_INVALID_CALL');
            if (call.id !== undefined) {
              if (typeof call.id !== 'string' || !call.id || call.id.length > 256 || seenIds.has(call.id) || batchIds.has(call.id)) fail('AI_TOOL_INVALID_CALL');
              batchIds.add(call.id);
            }
          }
        } else if (withTools && input.mode === 'SEPARATE') {
          // A plain research response cannot replace the final structured contract.
          forceFinal = true;
        } else {
          finalRaw = texts.join('');
          try { if (!object(JSON.parse(finalRaw))) fail('AI_TOOL_INVALID_FINAL'); } catch { fail('AI_TOOL_INVALID_FINAL'); }
          try { value = input.parseFinal ? input.parseFinal(finalRaw) : finalRaw as T; } catch { fail('AI_TOOL_INVALID_FINAL'); }
        }
        outcome = 'SUCCEEDED';
      } catch (error) {
        errorCode = controller.signal.aborted ? 'AI_TOOL_STOPPED' : safeError(error);
        if (error instanceof GeminiSafetyBlockedError || error instanceof GeminiCreditsUnavailableError) throw error;
        throw new Error(errorCode);
      } finally {
        if (dispatched) {
          if (currentUsage) addUsage(usage, currentUsage);
          if (!currentUsage) usageComplete = false;
          // Unknown usage reserves the whole allocation, never frees it as a measured zero.
          spentOutputTokens += currentUsage ? currentUsage.outputTokens : maxOutputTokens;
        }
        const report: GeminiAttemptReport = { ...admission, reservationId: receipt.reservationId, dispatched,
          outcome, httpStatus, usage: currentUsage, cumulativeUsage: { ...usage }, usageComplete,
          attemptUsageComplete: currentUsage !== null,
          candidateTokens: currentCandidates, thoughtTokens: currentThoughts,
          cachedPromptTokens: currentCached, toolUsePromptTokens: currentToolPrompt, errorCode };
        try {
          await measureAiPhase('ACCOUNTING', () => account(report));
        } catch {
          accountingComplete = false;
          // A valid final answer is deliverable, but accounting failure never admits another call.
          if (finalRaw === undefined) fail('AI_TOOL_ACCOUNTING_FAILED');
        }
      }
      if (spentOutputTokens > limits.maxTurnOutputTokens) fail('AI_TOOL_TOKEN_BUDGET');
      if (finalRaw !== undefined && directAttempt) {
        check();
        let accepted: boolean;
        try {
          accepted = await wait(Promise.resolve().then(() => input.directFirst!.accept(finalRaw!)));
          check();
          if (typeof accepted !== 'boolean') fail('AI_TOOL_DIRECT_CHECK_FAILED');
        } catch {
          return fail(controller.signal.aborted ? 'AI_TOOL_STOPPED' : 'AI_TOOL_DIRECT_CHECK_FAILED');
        }
        if (!accepted) {
          // Even though JSON was valid, it is not deliverable yet. In particular,
          // a failed accounting acknowledgement must never purchase this follow-up.
          if (!accountingComplete) fail('AI_TOOL_ACCOUNTING_FAILED');
          if (attempts > limits.maxToolRounds) fail('AI_TOOL_TURN_BUDGET');
          contents.push(modelContent, { role: 'user', parts: [{ text:
            'The preceding candidate is unverified and has not been applied or shown to the person. '
            + 'Use the available catalog tools to resolve the remaining classification against CURRENT evidence. '
            + 'Return the COMPLETE required JSON for the original user turn, preserving its useful facts, '
            + 'corrections and partial answers. Do not treat the candidate as user consent or invent missing results.' }] });
          continue;
        }
      }
      if (finalRaw !== undefined) return { value: value as T, raw: finalRaw, usage: { ...usage }, usageComplete, accountingComplete, attempts, toolCalls };
      if (calls.length) {
        // The model's calls in ONE response are independent. Validate the whole batch above,
        // then read concurrently under the same deadline; Promise.all preserves response order.
        for (const call of calls) {
          if (typeof call.id === 'string') seenIds.add(call.id);
        }
        toolCalls += calls.length;
        let results: JsonObject[];
        try {
          results = await measureAiPhase('CATALOG_TOOLS', () => wait(Promise.all(calls.map(async (call): Promise<JsonObject> => {
            check();
            const tool = toolMap.get(call.name as string)!;
            let result: JsonObject;
            try { result = await wait(tool.execute(call.args as JsonObject, { signal: controller.signal, callId: call.id as string | undefined, round: rounds + 1 })); }
            catch { return fail(controller.signal.aborted ? 'AI_TOOL_STOPPED' : 'AI_TOOL_READ_FAILED'); }
            let encoded: string;
            try { encoded = JSON.stringify(result); } catch { return fail('AI_TOOL_INVALID_RESULT'); }
            if (!object(result) || !encoded) fail('AI_TOOL_INVALID_RESULT');
            if (bytes(encoded) > limits.maxToolResultBytes) fail('AI_TOOL_RESULT_TOO_LARGE');
            return { functionResponse: { name: call.name, ...(call.id === undefined ? {} : { id: call.id }), response: JSON.parse(encoded) } };
          }))));
        } catch (error) {
          const code = controller.signal.aborted ? 'AI_TOOL_STOPPED' : safeError(error);
          stop(); // Cancel sibling reads after the first failure; no subsequent paid request.
          return fail(code);
        }
        contents.push(modelContent, { role: 'user', parts: results });
        rounds++;
      }
    }
    return fail('AI_TOOL_TURN_BUDGET');
  } finally {
    clearTimeout(timeout); input.signal?.removeEventListener('abort', stop); controller.abort();
  }
}

// A logical conversation turn can include several READ-ONLY model/tool rounds.
// Every paid request has its own durable reservation and immutable usage row.
import { AI_TEST_LIMITS, reserveAiTestBudget } from './aiTestBudget.ts';
import { decodeGeminiUsage } from './geminiTaskStream.ts';
import type { GeminiAttemptAdmission, GeminiAttemptReport } from './geminiToolConversation.ts';

export async function taxonomyRoundOperationId(accountId: string, conversationId: string, operationId: string, attempt: number): Promise<string> {
  if (!Number.isInteger(attempt) || attempt < 1 || attempt > 4) throw new Error('AI_TOOL_ATTEMPT_INVALID');
  if (attempt === 1) return operationId;
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(
    ['USKOCI_TAXONOMY_PROVIDER_ROUND_V1',accountId,conversationId,operationId,String(attempt)].join('|'))));
  // Application-defined, deterministic UUIDv8; never masquerades as UUIDv5/SHA1.
  digest[6] = (digest[6] & 15) | 128; digest[8] = (digest[8] & 63) | 128;
  const h = Array.from(digest.slice(0,16), v => v.toString(16).padStart(2,'0')).join('');
  return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;
}

/** The one BG attempt for this logical turn never shares the foreground key.
 * Purpose/account/conversation prevent cross-flow reuse; model/input changes do
 * not create a fresh paid key for replay of an already dispatched turn. */
export async function backgroundTaxonomyOperationId(input: {
  accountId: string; conversationId: string; operationId: string; purpose: 'NEED_INTAKE' | 'PROFILE';
}): Promise<string> {
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (![input.accountId, input.conversationId, input.operationId].every(value => uuid.test(value))
    || !['NEED_INTAKE', 'PROFILE'].includes(input.purpose)) throw new Error('AI_BG_IDENTITY_INVALID');
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(JSON.stringify([
    'USKOCI_TAXONOMY_BACKGROUND_V1', input.accountId.toLowerCase(), input.conversationId.toLowerCase(),
    input.operationId.toLowerCase(), input.purpose,
  ]))));
  digest[6] = (digest[6] & 15) | 128; digest[8] = (digest[8] & 63) | 128;
  const h = Array.from(digest.slice(0, 16), v => v.toString(16).padStart(2, '0')).join('');
  return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;
}

export function createBackgroundTaxonomyProviderBudget(input: {
  supabaseUrl: string; serviceRoleKey: string; accountId: string; conversationId: string;
  operationId: string; purpose: 'NEED_INTAKE' | 'PROFILE'; model: string;
}) {
  let started = false;
  let ledger: ReturnType<typeof createTaxonomyProviderBudget> | undefined;
  let admission: GeminiAttemptAdmission | undefined;
  return {
    async beforeAttempt(event: { requestBytes: number; signal?: AbortSignal }) {
      if (started) throw new Error('AI_BG_ATTEMPT_CONFLICT');
      started = true;
      if (!Number.isSafeInteger(event.requestBytes) || event.requestBytes <= 0
        || event.requestBytes > AI_TEST_LIMITS.llmRequestBytes || event.signal?.aborted) throw new Error('AI_BG_BUDGET_UNAVAILABLE');
      const operationId = await backgroundTaxonomyOperationId(input);
      const reservation = await reserveAiTestBudget({ ...input, operationId, kind: 'LLM', signal: event.signal });
      if (!reservation.admitted || reservation.replay || !reservation.reservationId) throw new Error('AI_BG_BUDGET_UNAVAILABLE');
      ledger = createTaxonomyProviderBudget({ ...input, operationId, firstReservationId: reservation.reservationId });
      admission = { attempt: 1, phase: 'FINAL', requestBytes: event.requestBytes,
        maxOutputTokens: 1024, signal: event.signal ?? new AbortController().signal };
      return ledger.beforeAttempt(admission);
    },
    async onAttempt(event: { reservationId: string; dispatched: boolean; outcome: 'SUCCEEDED' | 'FAILED';
      httpStatus: number | null; usageMetadata: unknown; errorCode: string | null }) {
      if (!ledger || !admission) throw new Error('AI_BG_ATTEMPT_CONFLICT');
      const details = decodeGeminiUsage(event.usageMetadata);
      await ledger.onAttempt({ ...admission, ...event, ...details,
        // An absent/invalid usage record is UNKNOWN. It never creates a zero
        // ledger row or releases the existing durable reservation.
        cumulativeUsage: details.usage ?? { promptTokens: 0, outputTokens: 0, totalTokens: 0 },
        attemptUsageComplete: details.usage !== null, usageComplete: details.usage !== null,
      });
    },
  };
}

export function createTaxonomyProviderBudget(input: {
  supabaseUrl: string; serviceRoleKey: string; accountId: string; conversationId: string;
  operationId: string; firstReservationId: string; model: string;
}) {
  let nextAttempt = 1;
  const attempts = new Map<number,{operationId:string;reservationId:string;settled:boolean}>();
  return {
    async beforeAttempt(event: GeminiAttemptAdmission) {
      if (event.attempt !== nextAttempt || event.attempt > 4) throw new Error('AI_TOOL_ATTEMPT_INVALID');
      const operationId = await taxonomyRoundOperationId(input.accountId,input.conversationId,input.operationId,event.attempt);
      let reservationId = input.firstReservationId;
      if (event.attempt > 1) {
        const reservation = await reserveAiTestBudget({supabaseUrl:input.supabaseUrl,serviceRoleKey:input.serviceRoleKey,
          accountId:input.accountId,operationId,kind:'LLM',signal:event.signal});
        if (!reservation.admitted || reservation.replay || !reservation.reservationId) throw new Error('AI_TOOL_BUDGET_UNAVAILABLE');
        reservationId = reservation.reservationId;
      }
      if (!reservationId) throw new Error('AI_TOOL_BUDGET_UNAVAILABLE');
      attempts.set(event.attempt,{operationId,reservationId,settled:false}); nextAttempt++;
      return {reservationId};
    },
    async onAttempt(event: GeminiAttemptReport) {
      const admitted = attempts.get(event.attempt);
      if (!admitted || admitted.reservationId !== event.reservationId || admitted.settled) throw new Error('AI_TOOL_USAGE_CONFLICT');
      admitted.settled = true;
      // Count-only observability. Never log the event itself: it also contains a
      // reservation identity. Cached input is a subset, not a second billed count.
      const count = (value: unknown) => typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value : null;
      try {
        console.info('AI_PROVIDER_USAGE', {
          attempt: count(event.attempt), phase: event.phase === 'TOOLS' || event.phase === 'FINAL' ? event.phase : 'UNKNOWN',
          requestBytes: count(event.requestBytes), model: input.model === 'gemini-3.8-flash' ? input.model : 'UNKNOWN',
          outcome: event.outcome === 'SUCCEEDED' || event.outcome === 'FAILED' ? event.outcome : 'UNKNOWN',
          promptTokens: count(event.usage?.promptTokens), outputTokens: count(event.usage?.outputTokens),
          candidateTokens: count(event.candidateTokens), thoughtTokens: count(event.thoughtTokens),
          cachedPromptTokens: count(event.cachedPromptTokens), toolUsePromptTokens: count(event.toolUsePromptTokens),
          usageComplete: event.attemptUsageComplete === true, cumulativeUsageComplete: event.usageComplete === true,
        });
      } catch { /* Observability cannot prevent usage settlement or answer delivery. */ }
      // Unknown outcomes retain the whole reservation. Missing usage is never 0.
      if (!event.usage || !event.attemptUsageComplete) return;
      const abort = new AbortController();
      const stopped = new Promise<never>((_, reject) => {
        abort.signal.addEventListener('abort', () => reject(new Error('AI_TOOL_USAGE_UNAVAILABLE')), { once: true });
      });
      void stopped.catch(() => undefined);
      const timer = setTimeout(() => abort.abort(), 3000);
      const check = () => { if (abort.signal.aborted) throw new Error('AI_TOOL_USAGE_UNAVAILABLE'); };
      try {
        const request = fetch(input.supabaseUrl + '/rest/v1/rpc/rpc_ai_test_record_usage_service', {
          method:'POST',redirect:'error',signal:abort.signal,
          headers:{apikey:input.serviceRoleKey,Authorization:'Bearer '+input.serviceRoleKey,'Content-Type':'application/json'},
          body:JSON.stringify({p_operation_id:admitted.operationId,p_model:input.model,
            p_prompt_tokens:event.usage.promptTokens,p_output_tokens:event.usage.outputTokens,p_total_tokens:event.usage.totalTokens}),
        }).then(response => {
          if (abort.signal.aborted || !response.ok || response.redirected || !response.body) {
            try { void response.body?.cancel().catch(() => undefined); } catch { /* best effort cleanup */ }
            throw new Error('AI_TOOL_USAGE_UNAVAILABLE');
          }
          return response;
        });
        const response = await Promise.race([request, stopped]);
        check();
        const reader=response.body!.getReader(); let raw='',size=0; const decoder=new TextDecoder('utf-8', { fatal: true });
        try { for (;;) { const part=await Promise.race([reader.read(), stopped]); check(); if(part.done)break;
          size+=part.value.byteLength;if(size>4096)throw new Error('AI_TOOL_USAGE_INVALID');raw+=decoder.decode(part.value,{stream:true}); }
          raw+=decoder.decode();
        } finally { try { void reader.cancel().catch(()=>undefined); } catch { /* best effort cleanup */ } }
        check();
        const receipt=JSON.parse(raw);
        if (receipt?.operationId!==admitted.operationId || typeof receipt.recorded!=='boolean' || receipt.authoritative!==true ||
          receipt.promptTokens!==event.usage.promptTokens || receipt.outputTokens!==event.usage.outputTokens || receipt.totalTokens!==event.usage.totalTokens)
          throw new Error('AI_TOOL_USAGE_INVALID');
      } finally { clearTimeout(timer); abort.abort(); }
    },
  };
}

